CREATE OR REPLACE FUNCTION public.cleanup_expired_rate_limit_buckets(p_older_than interval DEFAULT '24:00:00'::interval)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  deleted_count integer;
begin
  delete from public.rate_limit_buckets
  where reset_at < timezone('utc', now()) - p_older_than;

  get diagnostics deleted_count = row_count;
  return deleted_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.consume_rate_limit_bucket(p_bucket_key text, p_max_requests integer, p_window_ms integer)
 RETURNS TABLE(allowed boolean, remaining integer, reset_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  bucket public.rate_limit_buckets%rowtype;
  now_at timestamptz := now();
  next_reset timestamptz := now() + (greatest(p_window_ms, 1000)::text || ' milliseconds')::interval;
begin
  if p_bucket_key is null or length(trim(p_bucket_key)) = 0 then
    raise exception 'bucket_key is required';
  end if;

  if p_max_requests <= 0 then
    raise exception 'max_requests must be positive';
  end if;

  insert into public.rate_limit_buckets (bucket_key, request_count, reset_at)
  values (p_bucket_key, 0, next_reset)
  on conflict (bucket_key) do nothing;

  select *
  into bucket
  from public.rate_limit_buckets
  where rate_limit_buckets.bucket_key = p_bucket_key
  for update;

  if bucket.reset_at <= now_at then
    update public.rate_limit_buckets
    set request_count = 1,
        reset_at = next_reset,
        updated_at = now_at
    where rate_limit_buckets.bucket_key = p_bucket_key;

    allowed := true;
    remaining := greatest(p_max_requests - 1, 0);
    reset_at := next_reset;
    return next;
    return;
  end if;

  if bucket.request_count >= p_max_requests then
    allowed := false;
    remaining := 0;
    reset_at := bucket.reset_at;
    return next;
    return;
  end if;

  update public.rate_limit_buckets
  set request_count = bucket.request_count + 1,
      updated_at = now_at
  where rate_limit_buckets.bucket_key = p_bucket_key;

  allowed := true;
  remaining := greatest(p_max_requests - bucket.request_count - 1, 0);
  reset_at := bucket.reset_at;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.consume_user_credits(p_user_id uuid, p_organization_id uuid, p_amount integer, p_reason text, p_reference_type text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(allowed boolean, balance integer, ledger_id uuid, reused_existing boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_balance integer;
  next_balance integer;
  overdraft_limit integer := 2000;
  existing_ledger public.user_credit_ledger%rowtype;
  inserted_ledger public.user_credit_ledger%rowtype;
begin
  if p_user_id is null then
    raise exception 'user_id is required';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'credit amount must be positive';
  end if;

  if p_reason is null or length(trim(p_reason)) = 0 then
    raise exception 'credit reason is required';
  end if;

  if p_idempotency_key is not null then
    select *
      into existing_ledger
      from public.user_credit_ledger
     where idempotency_key = p_idempotency_key
       and user_id = p_user_id
     limit 1;

    if found then
      return query select true, existing_ledger.balance_after, existing_ledger.id, true;
      return;
    end if;
  end if;

  insert into public.user_credits (user_id, balance)
  values (p_user_id, 0)
  on conflict (user_id) do nothing;

  select uc.balance
    into current_balance
    from public.user_credits uc
   where uc.user_id = p_user_id
   for update;

  next_balance := current_balance - p_amount;

  if next_balance < -overdraft_limit then
    return query select false, current_balance, null::uuid, false;
    return;
  end if;

  update public.user_credits
     set balance = next_balance,
         updated_at = now()
   where user_id = p_user_id;

  insert into public.user_credit_ledger (
    user_id,
    organization_id,
    delta,
    balance_after,
    reason,
    reference_type,
    reference_id,
    idempotency_key,
    metadata
  )
  values (
    p_user_id,
    p_organization_id,
    -p_amount,
    next_balance,
    trim(p_reason),
    nullif(trim(coalesce(p_reference_type, '')), ''),
    nullif(trim(coalesce(p_reference_id, '')), ''),
    nullif(trim(coalesce(p_idempotency_key, '')), ''),
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'overdrafted',
      next_balance < 0,
      'overdraftLimitCents',
      overdraft_limit
    )
  )
  returning * into inserted_ledger;

  return query select true, next_balance, inserted_ledger.id, false;
end;
$function$

